'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { RefreshCwIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import { surfaceCollapseOf } from './_parts/collapse';

export default function Notification16() {
  const [isVisible, setIsVisible] = useState(true);
  const shouldReduceMotion = usePrefersReducedMotion();
  const leaveVariants = surfaceCollapseOf(shouldReduceMotion);

  function dismiss() {
    setIsVisible(false);
  }

  return (
    <AnimatePresence initial={false}>
      {isVisible && (
        <motion.div
          key='notification'
          role='status'
          className='surface-raised flex w-full max-w-100 items-start gap-3 overflow-hidden rounded-2xl p-4'
          variants={leaveVariants}
          initial='hidden'
          animate='shown'
          exit='hidden'
        >
          <StatusOrb
            tone='brand'
            glyph={<RefreshCwIcon strokeWidth={2.25} />}
          />
          <div className='flex grow flex-col gap-3 pt-1.5'>
            <div className='flex flex-col gap-1 text-[13px] leading-5'>
              <p className='font-medium'>Version 2.4 is ready to install</p>
              <p className='text-muted-foreground'>
                This update fixes sync on slow networks and makes search faster.
              </p>
            </div>
            <div className='flex gap-2'>
              <Button size='sm'>Install</Button>
              <Button size='sm' variant='ghost' onClick={dismiss}>
                Later
              </Button>
            </div>
          </div>
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label='Dismiss notification'
            className='text-muted-foreground -me-1.5 -mt-1.5'
            onClick={dismiss}
          >
            <XIcon />
          </Button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import type { Transition, Variants } from 'motion/react';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

/**
 * The spring AnimatedSize resizes with. It starts from rest, so the fade leads and the freed space
 * closes after it at the pace the surrounding container follows, instead of snapping shut.
 */
const SIZE_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.32 };

const ARRIVE: Transition = {
  ...SIZE_SPRING,
  opacity: { duration: 0.2, ease: EASE_OUT_STRONG },
};

const LEAVE: Transition = {
  ...SIZE_SPRING,
  opacity: { duration: 0.12, ease: EASE_OUT_STRONG },
};

const ARRIVE_FADE: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const LEAVE_FADE: Transition = { duration: 0.12, ease: EASE_OUT_STRONG };

/** A row whose spacing sits inside it: only its height and opacity change. */
const ROW_VARIANTS: Variants = {
  shown: { height: 'auto', opacity: 1, transition: ARRIVE },
  hidden: { height: 0, opacity: 0, transition: LEAVE },
};

/** A padded surface dismissed for good: its padding closes with its height. */
const SURFACE_VARIANTS: Variants = {
  shown: { height: 'auto', opacity: 1, transition: ARRIVE },
  hidden: {
    height: 0,
    opacity: 0,
    paddingTop: 0,
    paddingBottom: 0,
    transition: LEAVE,
  },
};

const FADE_VARIANTS: Variants = {
  shown: { opacity: 1, transition: ARRIVE_FADE },
  hidden: { opacity: 0, transition: LEAVE_FADE },
};

export function rowCollapseOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ROW_VARIANTS;
}

export function surfaceCollapseOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SURFACE_VARIANTS;
}
